function Modal({title,children,onClose,footer,variant}){const ref=useRef();useEffect(()=>{const previous=document.activeElement;const node=ref.current;node.querySelector('input,button,select,textarea')?.focus();const handle=e=>{if(e.key==='Escape'){e.preventDefault();onClose();}if(e.key==='Tab'){const items=[...node.querySelectorAll('button:not(:disabled),input:not(:disabled),select,textarea,[tabindex="0"]')];const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}};document.addEventListener('keydown',handle);const overflow=document.body.style.overflow;document.body.style.overflow='hidden';return()=>{document.removeEventListener('keydown',handle);document.body.style.overflow=overflow;previous?.focus();};},[]);return <div className={'overlay '+(variant==='sheet'?'sheet-overlay':'')} onMouseDown={e=>e.target===e.currentTarget&&onClose()}><section className="modal" ref={ref} role="dialog" aria-modal="true" aria-labelledby="modal-title"><header><h2 id="modal-title">{title}</h2><IconButton icon={X} label="Close / ปิด" onClick={onClose}/></header><div className="modal-body">{children}</div>{footer&&<footer>{footer}</footer>}</section></div>;}
