 const [demo,setDemo]=useState(()=>!supabase||localGet('tt-demo',false));const [user,setUser]=useState(null);const [authLoading,setAuthLoading]=useState(!!supabase);const [workspaceData,setData]=useState(emptyData);const data=activeData(workspaceData);const dataRef=useRef(workspaceData);dataRef.current=workspaceData;
