 useEffect(()=>{if(!supabase){setAuthLoading(false);return;}let live=true;supabase.auth.getSession().then(({data,error})=>{if(!live)return;if(error)notify(error.message,'error');setUser(data.session?.user||null);if(data.session)setDemo(false);setAuthLoading(false);});const {data:listener}=supabase.auth.onAuthStateChange((event,session)=>{setUser(session?.user||null);if(session){setDemo(false);localStorage.setItem('tt-demo','false');}if(event==='PASSWORD_RECOVERY')setRecovery(true);});return()=>{live=false;listener.subscription.unsubscribe();};},[]);
