 async function commit(changes,message){if(busyRef.current)return false;busyRef.current=true;setBusy(true);try{let next={...dataRef.current};for(const {kind,item,deleted} of changes){next[kind]=updateRecordList(next[kind],{...item,...(!demo?{_revision:(item._revision||0)+1}:{})},deleted);}if(demo)localStorage.setItem('tt-demo-data',JSON.stringify(next));else await commitCloud(changes);setData(next);if(message)notify(message);return true;}catch(e){if(e.message?.includes('TRACKER_CONFLICT')||e.code==='23505'){notify(t('conflict'),'error');try{setData(await readCloud());}catch{}}else notify(demo?t('storageError'):t('cloudError')+' '+e.message,'error');return false;}finally{busyRef.current=false;setBusy(false);}}
