 async function finishTimer(withBreak=false){const v=timerRef.current;if(!v)return true;if(v.phase==='break'){setPersistentTimer(null);return true;}const chunks=timerSlices(v);const existing=new Set(dataRef.current.focusSessions.map(s=>s.id));const changes=chunks.filter(s=>!existing.has(s.id)).map(item=>({kind:'focusSessions',item}));if(changes.length&&!await commit(changes,t('sessionSaved')))return false;if(withBreak&&v.breakMinutes>0)setPersistentTimer({id:uid(),phase:'break',startedAt:Date.now(),targetMinutes:v.breakMinutes,elapsedBefore:0});else setPersistentTimer(null);return true;}
