 const filteredTasks=data.tasks.filter(task=>(task.text+' '+task.tag).toLowerCase().includes(query.toLowerCase())).filter(task=>taskFilter==='all'||taskFilter==='active'&&!task.done||taskFilter==='completed'&&task.done||taskFilter==='high'&&task.priority==='high'||taskFilter==='overdue'&&!task.done&&task.dueDate&&task.dueDate<today).sort((a,b)=>Number(a.done)-Number(b.done)||({high:3,medium:2,low:1}[b.priority]-{high:3,medium:2,low:1}[a.priority])||(a.dueDate||'9999').localeCompare(b.dueDate||'9999')||b.createdAt-a.createdAt);
