function Editor({editor,t,language,busy,onClose,onSubmit}){const {kind,item,seed}=editor;const [form,setForm]=useState(()=>({name:'',emoji:kind==='subjects'?'study':'target',text:'',tag:'',priority:'low',dueDate:'',subtasks:[],days:[],target:1,unit:'',title:'',body:'',start:'09:00',end:'10:00',category:'',color:!item?(kind==='timeblocks'?colors.indigo:kind==='habits'?habitPalette[0]:''):'',day:weekday(dateKey()),...seed,...item}));const [subtext,setSubtext]=useState(()=>item?.subtasks?.map(s=>s.text).join('\n')||'');const [ideaCategory,setIdeaCategory]=useState('popular');const update=(key,value)=>setForm(f=>({...f,[key]:value}));const title=item?t('edit')+' '+t(kind==='timeblocks'?'schedule':kind==='subjects'?'category':kind):t({habits:'addHabit',tasks:'addTask',timeblocks:'addBlock',notes:'addNote',subjects:'addSubject',profile:'profile'}[kind]);function submit(e){e.preventDefault();let values={};if(kind==='habits')values={name:form.name.trim(),emoji:resolveIcon(form.emoji),target:Number(form.target),unit:form.unit.trim(),days:form.days,logs:item?.logs||[],color:normalizeScheduleColor(form.color),description:(form.description||'').trim()};if(kind==='tasks')values={text:form.text.trim(),tag:form.tag.trim(),priority:form.priority,dueDate:e.currentTarget.elements.namedItem('dueDate')?.value||'',done:item?.done||false,subtasks:reconcileSubtasks(subtext,item?.subtasks||[])};if(kind==='subjects')values={name:form.name.trim(),emoji:resolveIcon(form.emoji,'study')};if(kind==='notes')values={title:form.title.trim(),body:form.body.trim()};if(kind==='timeblocks')values={title:form.title.trim(),start:e.currentTarget.elements.namedItem('start').value,end:e.currentTarget.elements.namedItem('end').value,category:form.category.trim(),color:normalizeScheduleColor(form.color),day:Number(form.day)};if(kind==='profile')values={name:form.name.trim(),avatar:resolveIcon(form.avatar,'user')};if(Object.values(values).some(v=>typeof v==='string'&&v.length>100000))return;if((values.name!==undefined&&!values.name)||(values.text!==undefined&&!values.text)||(values.title!==undefined&&!values.title)||(values.body!==undefined&&!values.body))return;onSubmit(values);}
 return <Modal title={title} onClose={onClose} footer={<><button type="button" className="secondary" disabled={busy} onClick={onClose}>{t('cancel')}</button><button type="submit" form="entity-editor-form" className="primary" disabled={busy}>{busy?t('saving'):t('save')}</button></>}><form id="entity-editor-form" onSubmit={submit} className={'editor-form editor-'+kind+(kind==='timeblocks'?' activity-form':'')}><fieldset disabled={busy} className="form-fields">{['habits','subjects'].includes(kind)&&<div className="editor-entity-preview" style={{'--habit-color':habitColor(form)}}><span><EntityIcon value={form.emoji} size={32}/></span><strong>{form.name.trim()||t(kind==='habits'?'addHabit':'addSubject')}</strong></div>}{['habits','subjects'].includes(kind)&&<><Field label={t('name')}><input maxLength="180" value={form.name} onChange={e=>update('name',e.target.value)} required/></Field><IconPicker value={form.emoji} onChange={value=>update('emoji',value)} language={language} t={t}/></>}
 {kind==='habits'&&<><Field label={t('description')}><input maxLength="300" value={form.description||''} onChange={e=>update('description',e.target.value)} placeholder={t('optional')}/></Field><fieldset className="schedule-color-field habit-color-field"><legend>{t('habitColor')}</legend><div className="schedule-color-panel"><div className="schedule-color-picker">{habitPalette.map((color,index)=><button type="button" key={color} className={'schedule-color-swatch '+(habitColor(form)===color?'selected':'')} style={{'--swatch-color':color}} aria-label={t('habitColor')+' '+(index+1)} aria-pressed={habitColor(form)===color} onClick={()=>update('color',color)}><i>{habitColor(form)===color&&<Check size={13}/>}</i></button>)}<label className={'schedule-custom-color '+(!habitPalette.includes(habitColor(form))?'selected':'')} style={{'--custom-color':habitColor(form)}} title={t('customColor')}><span className="schedule-custom-circle"><Plus size={16}/></span><input type="color" aria-label={t('customColor')} value={habitColor(form)} onChange={e=>update('color',e.target.value)}/></label></div></div></fieldset><div className="field-grid"><Field label={t('target')}><input type="number" min="1" max="100000" value={form.target} onChange={e=>update('target',e.target.value)} required/></Field><Field label={t('unit')}><input maxLength="40" value={form.unit} onChange={e=>update('unit',e.target.value)}/></Field></div><div className="field"><span>{t('days')}</span><div className="day-picker habit-day-picker">{[1,2,3,4,5,6,0].map(d=><button type="button" key={d} aria-label={language==='th'?['อาทิตย์','จันทร์','อังคาร','พุธ','พฤหัส','ศุกร์','เสาร์'][d]:dayNames.en[d]} className={form.days.includes(d)?'selected':''} onClick={()=>update('days',form.days.includes(d)?form.days.filter(x=>x!==d):[...form.days,d])}><span className="weekday-full" aria-hidden="true">{language==='th'?['อาทิตย์','จันทร์','อังคาร','พุธ','พฤหัส','ศุกร์','เสาร์'][d]:dayNames.en[d]}</span><span className="weekday-short" aria-hidden="true">{shortDayNames[language][d]}</span></button>)}</div></div>{!item&&<details className="habit-ideas"><summary>{t('ideas')}<ChevronRight size={16}/></summary><div className="filter-pills scroll">{Object.keys(habitIdeas).map(cat=><button type="button" key={cat} className={ideaCategory===cat?'selected':''} onClick={()=>setIdeaCategory(cat)}>{t(cat)}</button>)}</div><div className="ideas-grid">{habitIdeas[ideaCategory].map(idea=><button type="button" key={idea.name} onClick={()=>{update('name',language==='th'?(ideaThai[idea.name]||idea.name):idea.name);update('emoji',resolveIcon(idea.emoji));}}><span><EntityIcon value={idea.emoji} size={20}/></span>{language==='th'?(ideaThai[idea.name]||idea.name):idea.name}</button>)}</div></details>}</>}
 {kind==='tasks'&&<><Field label={t('tasks')}><input maxLength="500" value={form.text} onChange={e=>update('text',e.target.value)} required/></Field><div className="field-grid"><Field label={t('tag')}><input maxLength="80" value={form.tag} onChange={e=>update('tag',e.target.value)}/></Field><Field label={t('priority')}><select value={form.priority} onChange={e=>update('priority',e.target.value)}>{['low','medium','high'].map(p=><option value={p} key={p}>{t(p)}</option>)}</select></Field></div><Field label={t('dueDate')}><DateInput name="dueDate" value={form.dueDate} onChange={e=>update('dueDate',e.target.value)}/></Field><Field label={t('subtasks')}><textarea rows="4" maxLength="10000" value={subtext} onChange={e=>setSubtext(e.target.value)}/></Field></>}
 {kind==='notes'&&<><Field label={t('title')}><input maxLength="300" value={form.title} onChange={e=>update('title',e.target.value)} required/></Field><Field label={t('body')}><textarea rows="8" maxLength="100000" value={form.body} onChange={e=>update('body',e.target.value)} required/></Field></>}
 {kind==='timeblocks'&&<><Field label={t('title')}><input maxLength="180" value={form.title} onChange={e=>update('title',e.target.value)} required/></Field><div className="field-grid timeblock-time-fields"><Field label={t('startTime')}><input type="time" name="start" value={form.start} onChange={e=>update('start',e.target.value)} required/></Field><Field label={t('endTime')}><input type="time" name="end" value={form.end} onChange={e=>update('end',e.target.value)} required/></Field></div><Field label={t('day')}><select value={form.day} onChange={e=>update('day',e.target.value)}>{[1,2,3,4,5,6,0].map(d=><option value={d} key={d}>{dayNames[language][d]}</option>)}</select></Field><Field label={t('category')}><input maxLength="80" value={form.category} onChange={e=>update('category',e.target.value)} required/></Field><fieldset className="schedule-color-field"><legend><span>{t('tagColor')}</span><span className="schedule-tag-preview" style={{'--tag-color':scheduleColor(form)}}><i/>{form.category.trim()||t('category')}</span></legend><div className="schedule-color-panel"><div className="schedule-color-picker">{Object.entries(colors).filter(([name])=>name!=='violet').map(([name,color])=><button type="button" key={name} className={'schedule-color-swatch '+(normalizeScheduleColor(form.color)===color?'selected':'')} style={{'--swatch-color':color}} aria-label={t('color'+name[0].toUpperCase()+name.slice(1))} aria-pressed={normalizeScheduleColor(form.color)===color} title={t('color'+name[0].toUpperCase()+name.slice(1))} onClick={()=>update('color',color)}><i>{normalizeScheduleColor(form.color)===color&&<Check size={13}/>}</i></button>)}<label className={'schedule-custom-color '+(normalizeScheduleColor(form.color)&&!Object.entries(colors).some(([name,color])=>name!=='violet'&&color===normalizeScheduleColor(form.color))?'selected':'')} style={{'--custom-color':normalizeScheduleColor(form.color)||colors.indigo}} title={t('customColor')}><span className="schedule-custom-circle"><Plus size={16}/></span><input type="color" aria-label={t('customColor')} value={normalizeScheduleColor(form.color)||colors.indigo} onChange={e=>update('color',e.target.value)}/></label></div></div></fieldset></>}
 {kind==='profile'&&<><Field label={t('username')}><input maxLength="80" value={form.name} onChange={e=>update('name',e.target.value)} required/></Field><IconPicker value={form.avatar||'user'} onChange={value=>update('avatar',value)} language={language} t={t}/></>}
 </fieldset></form></Modal>;
}
function NoteCard({note,t,language,busy,edit,remove,notify}){const [expanded,setExpanded]=useState(false);return <article className="panel note-card"><span className="note-icon"><NotebookPen size={20}/></span><h2>{note.title}</h2><button className={'note-body '+(expanded?'expanded':'')} onClick={()=>setExpanded(!expanded)} title={t('expand')}>{note.body}</button><footer><span>{new Date(note.createdAt).toLocaleDateString(language==='th'?'th-TH':'en-US',{month:'short',day:'numeric',year:'numeric'})}</span><div><IconButton icon={Copy} label={t('copy')} onClick={async()=>{try{await navigator.clipboard.writeText(note.body);notify(t('copied'));}catch{notify(t('noteCopiedError'),'error');}}}/><IconButton icon={Pencil} label={t('edit')} disabled={busy} onClick={edit}/><IconButton icon={Trash2} label={t('delete')} disabled={busy} onClick={remove}/></div></footer></article>;}
function Timetable({data,today,now,language,t,day,view,edit,remove,start,busy}){const hourHeight=96;const pixelsPerMinute=hourHeight/60;const ref=useRef();useEffect(()=>{if(ref.current)ref.current.scrollTop=7*hourHeight;},[view]);const days=view==='daily'?[day]:[1,2,3,4,5,6,0];function segments(b,d){const start=Number(b.start.slice(0,2))*60+Number(b.start.slice(3));const duration=minutes(b.start,b.end);const end=start+duration;const parts=[];if(b.day===d)parts.push({top:start,height:Math.min(end,1440)-start});if(end>1440&&(b.day+1)%7===d)parts.push({top:0,height:end-1440});return parts;}
 return <section className="panel timetable-panel"><div className="timetable-scroll" ref={ref}><div className={'timetable '+(view==='weekly'?'weekly':'daily')} style={{'--hour-height':hourHeight+'px'}}><div className="time-labels"><div className="time-head">{t('time')}</div>{Array.from({length:24},(_,h)=><div key={h}>{String(h).padStart(2,'0')}:00</div>)}</div>{days.map(d=><div className="timetable-day" key={d}><div className={'timetable-header '+(d===weekday(today)?'current':'')}>{dayNames[language][d]}</div><div className="timetable-body">{Array.from({length:24},(_,i)=><div className="hour-line" key={i}/>)}{data.timeblocks.map(b=>segments(b,d).map((s,i)=><article key={b.id+'-'+i} className={'time-block '+(s.height<60?'compact-block ':'')+(s.height<30?'short-block':'')} style={{top:s.top*pixelsPerMinute,height:Math.max(s.height*pixelsPerMinute,28),borderColor:scheduleColor(b),'--block-color':scheduleColor(b)}}><button className="block-main" title={b.title+' '+b.start+'–'+b.end} disabled={busy} onClick={()=>start(b)}><strong>{b.title}</strong>{s.height>=30&&<span>{b.start}–{b.end}</span>}{s.height>=60&&<small className="block-category">{b.category}</small>}</button><div className="block-tools"><IconButton icon={Pencil} label={t('edit')} disabled={busy} onClick={()=>edit(b)}/><IconButton icon={Trash2} label={t('delete')} disabled={busy} onClick={()=>remove(b)}/></div></article>))}{d===weekday(today)&&<div className="current-time" style={{top:(new Date(now).getHours()*60+new Date(now).getMinutes())*pixelsPerMinute}}><i/></div>}</div></div>)}</div></div></section>;
}
function Auth({language,setLanguage,t,recovery,onRecovered,onDemo}){const [mode,setMode]=useState(recovery?'recovery':'login');const [busy,setBusy]=useState(false);const [message,setMessage]=useState(null);const [email,setEmail]=useState('');const [password,setPassword]=useState('');const [confirmation,setConfirmation]=useState('');const [name,setName]=useState('');useEffect(()=>{if(recovery)setMode('recovery');},[recovery]);const switchMode=next=>{setMode(next);setMessage(null);setPassword('');setConfirmation('');};async function submit(e){e.preventDefault();if(!supabase){setMessage({error:true,text:t('notConfigured')});return;}if((mode==='register'||mode==='recovery')&&(password.length<8||password!==confirmation)){setMessage({error:true,text:t(password.length<8?'passwordShort':'passwordMismatch')});return;}setBusy(true);setMessage(null);try{let result;if(mode==='login')result=await supabase.auth.signInWithPassword({email:email.trim(),password});if(mode==='register')result=await supabase.auth.signUp({email:email.trim(),password,options:{data:{username:name.trim()},emailRedirectTo:location.origin}});if(mode==='forgot')result=await supabase.auth.resetPasswordForEmail(email.trim(),{redirectTo:location.origin});if(mode==='recovery')result=await supabase.auth.updateUser({password});if(result.error)throw result.error;if(mode==='register'&&!result.data.session)setMessage({text:t('signupSent')});if(mode==='forgot')setMessage({text:t('resetSent')});if(mode==='recovery'){setMessage({text:t('saved')});history.replaceState({},'',location.pathname);onRecovered();}}catch(e){setMessage({error:true,text:e.message});}finally{setBusy(false);}}
return <div className="auth-page"><section className="auth-story"><a className="brand" href="#">Try-Tracker <span className="version">2.0</span></a><div><span className="eyebrow">TRY. TRACK. GROW.</span><h1>{t('authTitle')}</h1><p>{t('authDesc')}</p><div className="auth-feature-list">{[['habits',CheckCheck],['tasks',ListTodo],['focus',Timer]].map(([key,Icon])=><span key={key}><Icon size={20}/>{t(key)}</span>)}</div></div><span className="auth-bottom">Try-Tracker © 2026</span></section><section className="auth-form-area"><button className="language-btn auth-language" onClick={()=>setLanguage(language==='th'?'en':'th')}><Languages size={17}/>{language==='th'?'English':'ไทย'}</button><div className="auth-form-card"><h2>{t(mode==='register'?'register':mode==='forgot'?'forgot':mode==='recovery'?'newPassword':'login')}</h2><p className="muted">{mode==='login'?t('emailLogin'):t('authDesc')}</p>{!supabase&&<div className="info-box">{t('notConfigured')}</div>}<form onSubmit={submit}><fieldset disabled={busy||!supabase}>{mode==='register'&&<Field label={t('username')}><input autoComplete="nickname" value={name} maxLength="80" onChange={e=>setName(e.target.value)} required/></Field>}{mode!=='recovery'&&<Field label={t('email')}><input type="email" autoComplete="email" value={email} onChange={e=>setEmail(e.target.value)} required/></Field>}{mode!=='forgot'&&<Field label={t(mode==='recovery'?'newPassword':'password')}><input type="password" minLength={mode==='login'?1:8} autoComplete={mode==='login'?'current-password':'new-password'} value={password} onChange={e=>setPassword(e.target.value)} required/></Field>}{(mode==='register'||mode==='recovery')&&<Field label={t('confirmPassword')}><input type="password" autoComplete="new-password" value={confirmation} onChange={e=>setConfirmation(e.target.value)} required/></Field>}{mode==='login'&&<button type="button" className="text-btn forgot-link" onClick={()=>switchMode('forgot')}>{t('forgot')}</button>}<button className="primary full" type="submit">{busy?t('loading'):t(mode==='register'?'register':mode==='forgot'?'reset':mode==='recovery'?'updatePassword':'login')}</button></fieldset></form>{message&&<div className={message.error?'auth-error':'info-box'} role="status">{message.text}</div>}{mode!=='recovery'&&<><button className="text-btn auth-switch" onClick={()=>switchMode(mode==='login'?'register':'login')}>{t(mode==='login'?'register':'login')}</button><div className="auth-divider"/><button className="secondary full" onClick={onDemo}>{t('tryDemo')}</button></>}</div></section></div>;
}

const HabitRow=props=>props.page==='today'||props.habitLayout!=='list'?<HabitCard {...props}/>:<HabitListRow {...props}/>;
const HabitListRow=({habit,today,date=today,t,page,busy,changeHabit,openEditor,remove})=>{const done=habitDone(habit,date);const value=habitValue(habit,date);const unavailable=date>today||!dueHabit(habit,date);return <div key={habit.id} className={'habit-row '+(done?'is-done':'')}><span className="emoji-tile"><EntityIcon value={habit.emoji}/></span><div className="row-main"><strong>{habit.name}</strong><span className="row-meta"><Flame size={13}/>{streak(habit,today).current} {t('streak')}<span>·</span>{value}/{habit.target} {habit.unit||t('times')}</span></div><div className="habit-actions">{habit.target>1&&<IconButton icon={RotateCcw} label={t('undo')} disabled={busy||unavailable||value===0} onClick={()=>changeHabit(habit,date,0)}/>}<button className={'check-btn '+(done?'checked':'')} disabled={busy||unavailable} aria-label={done?t('undo'):t('finish')} onClick={()=>changeHabit(habit,date,done?0:Math.min(habit.target,value+1))}>{done?<Check size={18}/>:habit.target>1?<Plus size={18}/>:null}</button></div>{page==='habits'&&<div className="row-tools"><IconButton icon={Pencil} label={t('edit')} disabled={busy} onClick={()=>openEditor('habits',habit)}/><IconButton icon={Trash2} label={t('delete')} disabled={busy} onClick={()=>remove('habits',habit)}/></div>}</div>;};
const TaskRow=({task,t,today,page,busy,toggleTask,toggleSub,openEditor,remove,language})=><div key={task.id} className={'task-row '+(task.done?'is-done':'')} style={{'--item-color':task.priority==='high'?'#f27d98':task.priority==='medium'?'#f4bb62':'#67a7ed'}}>
 <button className={'check-btn '+(task.done?'checked':'')} disabled={busy} aria-label={task.done?t('undo'):t('finish')} onClick={()=>toggleTask(task)}>{task.done&&<Check size={16}/>}</button>
 <div className="row-main"><strong>{task.text}</strong><div className="row-meta"><span className={'pill priority-'+task.priority}>{t(task.priority)}</span>{task.tag&&<span className="tag">{task.tag}</span>}{task.dueDate&&<span className={!task.done&&task.dueDate<today?'danger':''}><CalendarDays size={13}/> {dateLabel(task.dueDate,language)}</span>}</div></div>
 {page==='tasks'&&task.subtasks?.length>0&&<div className="subtask-list">{task.subtasks.map(s=><label key={s.id}><input type="checkbox" checked={s.done} disabled={busy} onChange={()=>toggleSub(task,s)}/><span className={s.done?'strike':''}>{s.text}</span></label>)}</div>}
 <div className="row-tools"><IconButton icon={Pencil} label={t('edit')} disabled={busy} onClick={()=>openEditor('tasks',task)}/><IconButton icon={Trash2} label={t('delete')} disabled={busy} onClick={()=>remove('tasks',task)}/></div>
</div>;
const Stat=({label,value,icon:Icon,color,sub})=><div className="stat-card"><span className={'stat-icon '+color}><Icon size={20}/></span><span className="stat-label">{label}</span><strong>{value}</strong>{sub&&<small>{sub}</small>}</div>;
const SectionHead=({title,link,action,t,goto})=><div className="section-head"><h2>{title}</h2>{link&&<button className="text-btn" onClick={()=>goto(link)}>{t('viewAll')}<ArrowUpRight size={15}/></button>}{action}</div>;
const ActiveTimer=({timer,elapsed,t,busy,pauseTimer,finishTimer})=>{const timed=timer?.mode==='pomodoro'||timer?.phase==='break';const display=timed?Math.max(0,timer.targetMinutes*60-elapsed):elapsed;return <><div className={'timer-orbit '+(timer&&!timer.paused?'is-active':'')}><div className="timer-circle"><span className="eyebrow">{timer?.phase==='break'?t('break'):timer?.paused?t('paused'):timer?t('running'):t('focus')}</span><strong>{formatClock(timer?display:0)}</strong><span>{timer?.phase==='break'?t('break'):timer?<><EntityIcon value={timer.emoji} size={18}/> {timer.subject}</>:t('noActive')}</span></div></div>{timer&&<div className="timer-controls">{timer.phase!=='break'&&<button className="secondary" onClick={pauseTimer} disabled={busy}>{timer.paused?<Play size={16}/>:<Pause size={16}/>} {timer.paused?t('resume'):t('pause')}</button>}<button className="primary" disabled={busy} onClick={()=>finishTimer()}><Square size={15}/>{timer.phase==='break'?t('skipBreak'):t('stop')}</button></div>}{elapsed>43200&&<p className="danger center">{t('sessionLong')}</p>}</>;};
const Allocation=({values,t})=>{const total=Object.values(values).reduce((a,b)=>a+b,0);return <div className="allocation">{Object.entries(values).sort((a,b)=>b[1]-a[1]).map(([name,val])=><div className="allocation-row" key={name}><span><i style={{background:categoryColor(name)}}/>{name}</span><strong>{(val/60).toFixed(1)} {t('hours')}</strong><div className="allocation-track"><i style={{width:(val/total*100)+'%',background:categoryColor(name)}}/></div></div>)}{!total&&<Empty icon={ChartNoAxesCombined} text={t('noData')}/>}</div>;};


function ProfileAvatar({photo,crop,size=22}){return photo?<ProfileImage src={photo} crop={crop}/>:<EntityIcon value="user" size={size}/>;}
function ProfileForm({profile,accountId,t,language,busy,onSave,canChangePassword,onPasswordChange}){
 const initial=()=>({name:profile.name||'',...profileDetails(profile)});const [form,setForm]=useState(initial);
 const [currentPassword,setCurrentPassword]=useState('');const [newPassword,setNewPassword]=useState('');const [confirmation,setConfirmation]=useState('');const [passwordBusy,setPasswordBusy]=useState(false);const [passwordMessage,setPasswordMessage]=useState(null);const update=(key,value)=>setForm(f=>({...f,[key]:value}));
 async function changePassword(e){e.preventDefault();setPasswordMessage(null);const issue=passwordIssue(newPassword,confirmation);if(issue){setPasswordMessage({error:true,text:t(issue)});return;}setPasswordBusy(true);try{await onPasswordChange(currentPassword,newPassword);setCurrentPassword('');setNewPassword('');setConfirmation('');setPasswordMessage({text:t('passwordChanged')});}catch(error){setPasswordMessage({error:true,text:error.message});}finally{setPasswordBusy(false);}}
 return <div className="stack profile-form-stack"><section className="panel profile-edit-panel"><h2>{t('editAccount')}</h2><form onSubmit={e=>{e.preventDefault();if(form.name.trim())onSave({name:form.name.trim(),firstName:form.firstName.trim(),lastName:form.lastName.trim(),birthDate:form.birthDate,gender:form.gender});}}><fieldset disabled={busy||passwordBusy}><div className="field-grid profile-details-grid"><Field label={t('accountId')}><input value={accountId} readOnly/></Field><Field label="Username"><input maxLength="80" autoComplete="username" value={form.name} onChange={e=>update('name',e.target.value)} required/></Field><Field label={t('firstName')}><input maxLength="80" autoComplete="given-name" value={form.firstName} onChange={e=>update('firstName',e.target.value)}/></Field><Field label={t('lastName')}><input maxLength="80" autoComplete="family-name" value={form.lastName} onChange={e=>update('lastName',e.target.value)}/></Field><Field label={t('birthDate')}><DateInput min="1900-01-01" max={dateKey()} autoComplete="bday" value={form.birthDate} onChange={e=>update('birthDate',e.target.value)}/></Field><Field label={t('gender')}><GenderSelect t={t} value={form.gender} onChange={e=>update('gender',e.target.value)}/></Field></div><div className="form-footer"><button type="button" className="secondary" onClick={()=>{setForm(initial());}}>{t('cancel')}</button><button type="submit" className="primary">{busy?t('saving'):t('save')}</button></div></fieldset></form></section><section className="panel profile-edit-panel"><h2>{t('password')}</h2><p className="muted password-help">{t(canChangePassword?'passwordHint':'passwordConnectedOnly')}</p><form onSubmit={changePassword}><fieldset disabled={!canChangePassword||busy||passwordBusy}><Field label={t('currentPassword')}><input type="password" autoComplete="current-password" value={currentPassword} onChange={e=>setCurrentPassword(e.target.value)} required/></Field><div className="field-grid profile-details-grid"><Field label={t('newPassword')}><input type="password" minLength={8} autoComplete="new-password" value={newPassword} onChange={e=>setNewPassword(e.target.value)} required/></Field><Field label={t('confirmPassword')}><input type="password" minLength={8} autoComplete="new-password" value={confirmation} onChange={e=>setConfirmation(e.target.value)} required/></Field></div><button className="primary" type="submit">{passwordBusy?t('saving'):t('changePassword')}</button></fieldset></form>{passwordMessage&&<p className={passwordMessage.error?'auth-error':'info-box'} role="status">{passwordMessage.text}</p>}</section></div>;
}
